assertions.source:
assert descriptor["annotations"] == {
            "readOnlyHint": tool.name != "create_contribution_plan",
            "destructiveHint": False,
            "idempotentHint": True,
            "openWorldHint": False,
        }

assert (
        "textContent" in PLAN_WIDGET_HTML and "event.source !== window.parent" in PLAN_WIDGET_HTML
    )

assert any(
            p["name"] == "X-Idempotency-Key" and p["required"] for p in operation["parameters"]
        )

assert not await svc.fail_plan_job(
        claim, failure_code=PlanJobFailureCode.CALCULATION_FAILED, retryable=False
    )

assert all(
        p.value is None or p.value.currency.value == "EUR" for p in before.valuation.positions
    )

assert all(p.fx is None for p in before.valuation.positions), (
        "already converted materialized values must not receive FX twice"
    )

assert sum(
        (x.recommended_amount.amount for x in result.lines), Decimal(0)
    ) + result.summary.residual_cash.amount == Decimal("20")

assert sum(
            (line.recommended_amount.amount for line in detail.lines.items), Decimal(0)
        ) + detail.result.residual_cash.amount == Decimal("20")

assert next(x.target_weight for x in result.rows if x.key == "target/A") == Decimal(
        "0.166666666666666666"
    )

assert [x.recommended_amount.amount for x in result.lines] == [
            Decimal(x) for x in expected["allocations"]
        ]

assert result.summary.objective_after.scores == tuple(
            Decimal(x) for x in expected["scores"]
        )

assert (
        calculate_contribution_plan(
            replace(
                fixed,
                valuation=replace(
                    fixed.valuation,
                    positions=(future,),
                    sources=(*value.valuation.sources, future.fx.source),
                ),
            )
        ).summary.context.reason_code
        == "source_after_cutoff"
    )

assert (
            "private-service-detail" not in response.text
            and response.json()["error"]["details"] == {}
        )
